CREATE TABLE `refund_orders` (
`id` BIGINT NOT NULL AUTO_INCREMENT,`public_id` VARCHAR(36) NOT NULL,`refund_no` VARCHAR(34) NOT NULL,`order_id` BIGINT NOT NULL,`aftersale_id` BIGINT NOT NULL,`payment_order_id` BIGINT NOT NULL,`requested_by_admin_id` BIGINT NOT NULL,
`provider` ENUM('MOCK','DISABLED','WECHAT','ALIPAY') NOT NULL,`status` ENUM('CREATED','PENDING','SUCCEEDED','FAILED','UNKNOWN') NOT NULL DEFAULT 'CREATED',`amount_cent` INT UNSIGNED NOT NULL,`reason` VARCHAR(200) NOT NULL,`idempotency_key` VARCHAR(128) NOT NULL,`request_hash` CHAR(64) NOT NULL,`provider_refund_id` VARCHAR(128) NULL,`failure_reason` VARCHAR(64) NULL,`succeeded_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,
UNIQUE INDEX `refund_orders_public_id_key`(`public_id`),UNIQUE INDEX `refund_orders_refund_no_key`(`refund_no`),UNIQUE INDEX `refund_orders_idempotency_key_key`(`idempotency_key`),UNIQUE INDEX `refund_orders_provider_provider_refund_id_key`(`provider`,`provider_refund_id`),INDEX `refund_orders_order_id_created_at_idx`(`order_id`,`created_at`),INDEX `refund_orders_aftersale_id_idx`(`aftersale_id`),INDEX `refund_orders_requested_by_admin_id_idx`(`requested_by_admin_id`),PRIMARY KEY(`id`),
CONSTRAINT `refund_orders_order_id_fkey` FOREIGN KEY(`order_id`) REFERENCES `orders`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `refund_orders_aftersale_id_fkey` FOREIGN KEY(`aftersale_id`) REFERENCES `aftersales`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `refund_orders_payment_order_id_fkey` FOREIGN KEY(`payment_order_id`) REFERENCES `payment_orders`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `refund_orders_requested_by_admin_id_fkey` FOREIGN KEY(`requested_by_admin_id`) REFERENCES `admin_users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `refund_transactions` (`id` BIGINT NOT NULL AUTO_INCREMENT,`refund_order_id` BIGINT NOT NULL,`provider` ENUM('MOCK','DISABLED','WECHAT','ALIPAY') NOT NULL,`event_id` VARCHAR(128) NOT NULL,`provider_refund_id` VARCHAR(128) NOT NULL,`amount_cent` INT UNSIGNED NOT NULL,`occurred_at` DATETIME(3) NOT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE INDEX `refund_transactions_provider_event_id_key`(`provider`,`event_id`),UNIQUE INDEX `refund_transactions_provider_provider_refund_id_key`(`provider`,`provider_refund_id`),INDEX `refund_transactions_refund_order_id_created_at_idx`(`refund_order_id`,`created_at`),PRIMARY KEY(`id`),CONSTRAINT `refund_transactions_refund_order_id_fkey` FOREIGN KEY(`refund_order_id`) REFERENCES `refund_orders`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
